# Test solver cleanly
def solve_test(I):
    I=np.array(I); H,W=I.shape
    cnt=Counter(I.flatten()); bgv=cnt.most_common(1)[0][0]
    mc=[c for c,n in cnt.items() if n==4][0]
    ys,xs=np.where(I==mc); r0,r1,c0,c1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
    O=I[r0:r1+1,c0:c1+1].copy()
    strays=[(r,c,int(I[r,c])) for r in range(H) for c in range(W)
            if (r<r0 or r>r1 or c<c0 or c>c1) and I[r,c]!=bgv and I[r,c]!=mc]
    tr0,tr1,tc0,tc1=min(p[0] for p in strays),max(p[0] for p in strays),min(p[1] for p in strays),max(p[1] for p in strays)
    T=[[int(I[tr0+r][tc0+c]) for c in range(tc1-tc0+1)] for r in range(tr1-tr0+1)]
    for r in range(tr1-tr0+1):
        for c in range(tc1-tc0+1):
            if int(I[tr0+r][tc0+c])==bgv or int(I[tr0+r][tc0+c])==mc: T[r][c]=None
    # real anchor blocks: connected comps of non-bg,non-mc inside
    mask=np.zeros(O.shape,bool)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if I[r,c]!=bgv and I[r,c]!=mc: mask[r-r0,c-c0]=True
    lab,num=ndimage.label(mask.astype(int))
    binfo=[]
    for nm in range(1,num+1):
        pts=np.argwhere(lab==nm)
        rr0,rr1=pts[:,0].min(),pts[:,0].max(); cc0,cc1=pts[:,1].min(),pts[:,1].max()
        col=I[r0+rr0,c0+cc0]
        binfo.append((col,(r0+rr0,r0+rr1,c0+cc0,c0+cc1)))
    O_=O.copy()
    for col,(a,a1,a2,a3) in binfo:
        O_[a[0]:a[1]+1, a2:a3+1]=col
    # unanchored stray colors -> extend nearest colored block in same direction (like demos)
    ucolors=[int(T[r][c]) for r in range(len(T)) for c in range(len(T[0]))
             if T[r][c] not in {0,None,bgv,mc}]
    ucells={(r,c) for r in range(len(T)) for c in range(len(T[0])) if int(T[r][c]) in ucolors}
    for r in range(len(T)):
        for c in range(len(T[0])):
            if (r,c) in ucells:
                v=int(T[r][c])
                # find nearest neighbor block above/below/left/right
                cand=None
                for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nr,nc=r+dr,c+dc
                    while 0<=nr<len(O_) and 0<=nc<len(O_):
                        colv=O_[nr,nc]
                        if colv not in (bgv,mc):
                            # which block? get its extents
                            # try extending upward/downward from this block's bbox? use bounding info
                            cand=(colv,(nr,nc),dr,dc)
                        break
                    nr+=dr
                    nc+=dc
                if cand is None: continue
                _,(ar0,ar1),(_,_),dc,dn=cand
                O_[ar0:ar1+1, nc-dn] = v if dn!=0 else O_[ar0:ar1+1, nc] = v
                # fill up/down until edge of that block / next block boundary
                if dc==0:  # vertical extension
                    for rr in range(ar1+1, O_.shape[0]):
                        if O_[rr,nc-dn]==bgv:
                            O_[rr,nc-dn]=v
                        else: break
                if dr==0:  # horizontal
                    for cc in range(nc+1, O_.shape[1]):
                        if O_[ar0,cc]==bgv:
                            O_[ar0,cc]=v
                        else: break
    return O_,T,binfo

